import { epd } from './utils';

// Position graph generated by scripts/build-openings.mjs from the lichess
// chess-openings dataset (CC0).
export interface OpeningData {
  names: [string, string][];
  nodes: [string, number, [string, number][]][];
}

export interface Opening {
  eco: string;
  name: string;
}

export class OpeningBook {
  private index = new Map<string, number>();
  constructor(private data: OpeningData) {
    data.nodes.forEach(([key], i) => this.index.set(key, i));
  }

  has(fen: string): boolean {
    return this.index.has(epd(fen));
  }

  /** The opening name of this exact position, if it has one. */
  nameOf(fen: string): Opening | null {
    const i = this.index.get(epd(fen));
    if (i === undefined) return null;
    const n = this.data.nodes[i][1];
    if (n < 0) return null;
    const [eco, name] = this.data.names[n];
    return { eco, name };
  }

  /** Book continuations (UCI) from this position. */
  movesFrom(fen: string): string[] {
    const i = this.index.get(epd(fen));
    if (i === undefined) return [];
    return this.data.nodes[i][2].map(([uci]) => uci);
  }

  /**
   * Weight of each continuation: the number of named lines passing through
   * it. A decent proxy for popularity so bots prefer mainlines.
   */
  weightedMovesFrom(fen: string): { uci: string; weight: number }[] {
    const i = this.index.get(epd(fen));
    if (i === undefined) return [];
    return this.data.nodes[i][2].map(([uci, child]) => ({ uci, weight: this.subtreeSize(child) }));
  }

  private sizes = new Map<number, number>();
  private subtreeSize(i: number, depth = 0): number {
    const cached = this.sizes.get(i);
    if (cached !== undefined) return cached;
    if (depth > 40) return 1;
    let s = 1;
    for (const [, c] of this.data.nodes[i][2]) s += this.subtreeSize(c, depth + 1);
    this.sizes.set(i, s);
    return s;
  }

  /** Names the opening for a sequence of positions (latest named position wins). */
  classify(fens: string[]): Opening | null {
    for (let i = fens.length - 1; i >= 0; i--) {
      const o = this.nameOf(fens[i]);
      if (o) return o;
    }
    return null;
  }
}

let book: OpeningBook | null = null;
let loading: Promise<OpeningBook | null> | null = null;

export function setOpeningBook(data: OpeningData) {
  book = new OpeningBook(data);
  return book;
}

export function getOpeningBook(): OpeningBook | null {
  return book;
}

export function loadOpeningBook(): Promise<OpeningBook | null> {
  if (book) return Promise.resolve(book);
  if (!loading) {
    loading = fetch(`${import.meta.env.BASE_URL}openings.json`)
      .then((r) => (r.ok ? r.json() : Promise.reject(new Error(r.statusText))))
      .then((d: OpeningData) => setOpeningBook(d))
      .catch((e) => {
        console.warn('[openings] failed to load', e);
        loading = null;
        return null;
      });
  }
  return loading;
}
